exps = result['data']['experiments']

def find_keys_recursive(obj, target_patterns, path=''):
    '''Find all keys containing target patterns recursively'''
    findings = []
    if isinstance(obj, dict):
        for k, v in obj.items():
            current_path = f'{path}.{k}' if path else k
            kl = k.lower()
            for p in target_patterns:
                if p in kl:
                    findings.append((current_path, v))
                    break
            findings.extend(find_keys_recursive(v, target_patterns, current_path))
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            findings.extend(find_keys_recursive(item, target_patterns, f'{path}[{i}]'))
    return findings

